using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class QuotationComparison:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object Lookup(string type,int? parentID){return AssetBAL.Rows(S.Lookup(type,parentID));}[WebMethod]public static object List(long requestID){return AssetBAL.Rows(S.List("QuotationComparison",requestID));}[WebMethod]public static ApiResult Select(long id,long requestID,string reason){try{if(requestID<=0)return ApiResult.Fail("Select a purchase request.");if(string.IsNullOrWhiteSpace(reason))return ApiResult.Fail("Selection reason is required.");var quotations=S.List("QuotationComparison",requestID);var found=false;foreach(System.Data.DataRow row in quotations.Rows)if(Convert.ToInt64(row["QuotationID"])==id){found=true;break;}if(!found)return ApiResult.Fail("The quotation does not belong to the selected purchase request.");S.Action("Quotation",id,"Select",reason.Trim(),U);return ApiResult.Ok(null,"Final quotation selected successfully.");}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
